/* Conceptual extrusion of the actual metric polygon, clipped to its buildable envelope. */
function drawParcelScene(canvas){
 const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const W=r.width,H=r.height,g=state.lot.geometry,c=calc(),env=ParcelGeometry.inset(g),buildings=ParcelGeometry.footprint(g,c.footprint),p=g.vertices,xs=p.map(v=>v[0]),ys=p.map(v=>v[1]),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2,w=Math.max(...xs)-Math.min(...xs),d=Math.max(...ys)-Math.min(...ys),decor=canvas.dataset.canvas==='decor',scale=Math.min(W/(Math.hypot(w,d)*1.25),H/(Math.max(w,d)*.65+c.height*1.6))*state.zoom*.9,angle=state.rotation,el=state.elevation,origin=[W*.5,H*.67];
 const raw=(x,y,z=0)=>{x-=cx;y-=cy;const rx=x*Math.cos(angle)-y*Math.sin(angle),ry=x*Math.sin(angle)+y*Math.cos(angle);return [origin[0]+rx*scale,origin[1]+(ry*Math.sin(el)-z*Math.cos(el))*scale,ry*Math.cos(el)+z*Math.sin(el)]};
 const poly=(points,fill,stroke='#fff8',dash=[])=>{ctx.beginPath();points.forEach((v,i)=>{const q=raw(...v);i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1])});ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([])}};
 const line=(a,b,color='#1F8EA6',dash=[])=>{const x=raw(...a),y=raw(...b);ctx.beginPath();ctx.moveTo(x[0],x[1]);ctx.lineTo(y[0],y[1]);ctx.strokeStyle=color;ctx.lineWidth=1;ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([])};
 ctx.clearRect(0,0,W,H);const m=Math.max(w,d)*.75;if(!decor){for(let x=-m;x<=m;x+=Math.max(5,Math.ceil(m/20))) {line([cx+x,cy-m,-.1],[cx+x,cy+m,-.1],'#1f8ea61a');line([cx-m,cy+x,-.1],[cx+m,cy+x,-.1],'#1f8ea61a')}}
 poly(p.map(v=>[...v,0]),'#d9f0d9','#5A8F3D',[4,3]);if(state.setbacks)for(const path of env.paths)poly(path.map(v=>[...v,.03]),'#7ee2b866','#10B981',[3,4]);
 const faces=[];for(const building of buildings){for(let f=0;f<state.floors;f++){const z0=f*3+.1,z1=(f+1)*3;building.forEach((a,i)=>{const b=building[(i+1)%building.length],points=[[...a,z0],[...b,z0],[...b,z1],[...a,z1]];faces.push({points,depth:points.reduce((s,v)=>s+raw(...v)[2],0)/4,color:['#1F8EA6','#0F2D4A','#10B981','#1F8EA6'][i%4]})})}faces.push({points:building.map(v=>[...v,c.height]),depth:1e9,color:'#c8eadd'})}
 faces.sort((a,b)=>a.depth-b.depth);for(const face of faces)poly(face.points,face.color,'#eff4e2aa');
 if(state.envelope&&!decor)for(const path of env.paths)path.forEach((a,i)=>{const b=path[(i+1)%path.length];line([...a,0],[...a,24],'#1f8ea666',[3,4]);line([...a,24],[...b,24],'#1f8ea666',[3,4])});
 if(!decor){const a=p[g.front],b=p[(g.front+1)%p.length],q=raw((a[0]+b[0])/2,(a[1]+b[1])/2,0);ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillStyle='#0F2D4A';ctx.fillText('FRENTE · '+number(g.frontage,2)+' m',q[0],q[1]+20);ctx.textAlign='left';ctx.font='10px sans-serif';ctx.fillText('Geometria informada · massa conceitual',14,H-15);if(c.footprint<.01){ctx.font='13px sans-serif';ctx.fillStyle='#922626';ctx.fillText('Sem área de implantação após os recuos',14,25)}}
}
